<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>善意的谎言</title>
    <style>
        body {
            background-color: #2a2a2a;
            margin: 0;
            padding: 20px;
            display: flex;
            justify-content: center;
            font-family: 'KaiTi', 'Kaiti SC', 'STKaiti', '楷体', serif;
        }
        .page {
            position: relative;
            width: 800px;
            background-color: #fdfaf5;
            box-shadow: 0 10px 25px rgba(0,0,0,0.5);
            overflow: hidden;
            padding-bottom: 20px;
        }
        /* Top header representing the cut-off printed area */
        .header {
            height: 50px;
            border-bottom: 2px solid #d35400;
            display: flex;
            align-items: flex-end;
            justify-content: space-around;
            color: #d35400;
            font-size: 16px;
            font-family: sans-serif;
            padding-bottom: 5px;
            box-sizing: border-box;
            background-color: #fdfaf5;
            position: relative;
            z-index: 2;
        }
        .header-item {
            display: flex;
            align-items: flex-end;
        }
        .header-line {
            display: inline-block;
            width: 80px;
            border-bottom: 1px solid #d35400;
            margin-left: 5px;
            height: 10px;
        }
        /* The grid layer mimicking composition paper */
        .grid-layer {
            position: absolute;
            top: 50px; /* Start exactly below header */
            left: 0; 
            right: 0; 
            bottom: 0;
            pointer-events: none;
            background:
                /* Left margin double vertical line */
                linear-gradient(90deg, transparent 40px, rgba(211,84,0,0.85) 40px, rgba(211,84,0,0.85) 41px, transparent 41px),
                linear-gradient(90deg, transparent 43px, rgba(211,84,0,0.85) 43px, rgba(211,84,0,0.85) 44px, transparent 44px),
                /* Horizontal grid lines - exact 40px spacing */
                repeating-linear-gradient(to bottom, transparent, transparent 39px, rgba(211,84,0,0.4) 39px, rgba(211,84,0,0.4) 40px),
                /* Vertical grid lines - exact 30px spacing, starting after margin */
                repeating-linear-gradient(to right, transparent, transparent 29px, rgba(211,84,0,0.15) 29px, rgba(211,84,0,0.15) 30px);
            background-position: 0 0, 0 0, 0 0, 44px 0;
            z-index: 0;
        }
        /* The content layer containing the text */
        .content-layer {
            position: relative;
            z-index: 1;
            padding-top: 0; /* Aligned with grid */
        }
        .row {
            display: flex;
            height: 40px; /* Must perfectly match horizontal grid spacing */
            line-height: 40px;
            font-size: 21px;
            color: #1a1a1a;
        }
        .margin {
            width: 44px; /* Matches the space before the double line */
            flex-shrink: 0;
            text-align: right;
            padding-right: 4px;
            box-sizing: border-box;
            font-size: 18px;
            color: #1a1a1a;
        }
        .text {
            flex-grow: 1;
            padding-left: 6px; /* Slight padding away from double line */
            white-space: pre-wrap;
            letter-spacing: 1px;
        }
        .indent-title {
            padding-left: 40px; /* Rough indent for the title */
        }
        /* Styling for the inserted character "处" */
        .insertion-mark {
            position: relative;
            width: 0;
            display: inline-block;
        }
        .insertion-content {
            position: absolute;
            top: 15px;
            left: -12px;
            font-size: 15px;
            text-align: center;
            line-height: 1;
            color: #1a1a1a;
        }
        .caret {
            font-size: 12px;
            display: block;
            margin-top: 1px;
        }
    </style>
</head>
